declare module 'router_js/lib/transition-intent/url-transition-intent' {
    import type { Route } from "router_js/lib/route-info";
    import type Router from "router_js/lib/router";
    import { TransitionIntent } from "router_js/lib/transition-intent";
    import TransitionState from "router_js/lib/transition-state";
    export default class URLTransitionIntent<R extends Route> extends TransitionIntent<R> {
        preTransitionState?: TransitionState<R>;
        url: string;
        constructor(router: Router<R>, url: string, data?: object);
        applyToState(oldState: TransitionState<R>): TransitionState<R>;
    }
}